import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import { Textarea } from '../ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';
import { Upload, File, X, Cloud } from 'lucide-react';
import { documentService } from '../../services/documentService';
import { projectService } from '../../services/projectService';
import { clientService } from '../../services/clientService';
import { useAuth } from '../../contexts/AuthContext';
import Swal from 'sweetalert2';

export const UploadDocumentModalImproved = ({
  isOpen,
  onClose,
  onSuccess,
  clientId: initialClientId,
  currentFolderId,
  currentPath,
}) => {
  const { user } = useAuth();
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    document_type: 'report',
    project_id: '',
    folder_id: '',
    client_id: initialClientId || '',
  });
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [projects, setProjects] = useState([]);
  const [clients, setClients] = useState([]);
  const [dragActive, setDragActive] = useState(false);

  useEffect(() => {
    if (isOpen) {
      loadClients();
      // Actualizar folder_id cuando cambia currentFolderId
      setFormData((prev) => ({
        ...prev,
        folder_id: currentFolderId || '',
        client_id: initialClientId || '',
      }));
    }
  }, [isOpen, currentFolderId, initialClientId]);

  useEffect(() => {
    if (formData.client_id) {
      loadProjects();
    } else {
      setProjects([]);
    }
  }, [formData.client_id]);

  const loadClients = async () => {
    try {
      let data = [];
      
      // Si es consultor, cargar solo sus clientes asignados
      if (user?.role === 'user') {
        const { clientTeamService } = require('../../services/clientTeamService');
        const assignments = await clientTeamService.getConsultantClients(user._id);
        data = assignments.map(a => a.client_id);
      } else {
        // Admin y super admin ven todos
        data = await clientService.getAll();
      }
      
      setClients(data);
    } catch (error) {
      console.error('Error loading clients:', error);
    }
  };
    const loadProjects = async () => {
    try {
      if (formData.client_id) {
        const data = await projectService.getAll();
        const filtered = data.filter((p) => 
          p.client_id._id === formData.client_id || p.client_id === formData.client_id
        );
        setProjects(filtered);
      }
    } catch (error) {
      console.error('Error loading projects:', error);
    }
  };

  // Validar archivo
  const isValidFile = (selectedFile) => {
    if (selectedFile.size > 10485760) {
      Swal.fire('Error', 'El archivo es demasiado grande. Máximo 10MB', 'error');
      return false;
    }

    const allowedTypes = [
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'image/jpeg',
      'image/png',
    ];

    if (!allowedTypes.includes(selectedFile.type)) {
      Swal.fire('Error', 'Tipo de archivo no permitido. Usa: PDF, DOC, DOCX, XLS, XLSX, JPG, PNG', 'error');
      return false;
    }

    return true;
  };

  // Procesar archivo
  const handleFileSelect = (selectedFile) => {
    if (isValidFile(selectedFile)) {
      setFile(selectedFile);

      // Auto-llenar título si está vacío
      if (!formData.title) {
        setFormData((prev) => ({
          ...prev,
          title: selectedFile.name.replace(/\.[^/.]+$/, ''),
        }));
      }
    }
  };

  // Click en input
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      handleFileSelect(selectedFile);
    }
  };

  // Drag & Drop
  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    const selectedFile = e.dataTransfer.files[0];
    if (selectedFile) {
      handleFileSelect(selectedFile);
    }
  };

  const handleRemoveFile = () => {
    setFile(null);
    document.getElementById('file-input').value = '';
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!file) {
      Swal.fire('Error', 'Por favor selecciona un archivo', 'error');
      return;
    }

    if (!formData.title.trim()) {
      Swal.fire('Error', 'El título es requerido', 'error');
      return;
    }

    setLoading(true);
    setUploadProgress(0);

    try {
      const formDataToSend = new FormData();
      formDataToSend.append('file', file);
      formDataToSend.append('title', formData.title.trim());
      formDataToSend.append('description', formData.description.trim());
      formDataToSend.append('document_type', formData.document_type);

      // Agregar client_id si está disponible
      if (formData.client_id) {
        formDataToSend.append('client_id', formData.client_id);
      }

      // Solo agregar folder_id si tiene valor
      if (formData.folder_id) {
        formDataToSend.append('folder_id', formData.folder_id);
      }

      if (formData.project_id) {
        formDataToSend.append('project_id', formData.project_id);
      }

      await documentService.upload(formDataToSend, (progressEvent) => {
        const percentCompleted = Math.round(
          (progressEvent.loaded * 100) / progressEvent.total
        );
        setUploadProgress(percentCompleted);
      });

      Swal.fire({
        icon: 'success',
        title: 'Documento subido exitosamente',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 2000,
      });

      handleClose();
      onSuccess();
    } catch (error) {
      console.error('Upload error:', error);
      Swal.fire(
        'Error',
        error.response?.data?.detail || 'Error al subir documento',
        'error'
      );
    } finally {
      setLoading(false);
      setUploadProgress(0);
    }
  };

  const handleClose = () => {
    setFormData({
      title: '',
      description: '',
      document_type: 'report',
      project_id: '',
      folder_id: currentFolderId || '',
      client_id: initialClientId || '',
    });
    setFile(null);
    setUploadProgress(0);
    setDragActive(false);
    onClose();
  };

  const breadcrumbPath = currentPath.length > 0
    ? currentPath.map((p) => p.name).join(' / ')
    : 'Raíz';

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Upload className="w-5 h-5" />
            Subir Documento
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit}>
          <div className="space-y-4 py-4">
            {/* Cliente - Solo si no hay uno preseleccionado */}
            {!initialClientId && (
              <div>
                <Label htmlFor="client_id" className="font-semibold">
                  Cliente {formData.client_id ? '' : '(Opcional)'}
                </Label>
                <Select
                  value={formData.client_id || ''}
                  onValueChange={(value) =>
                    setFormData({ ...formData, client_id: value })
                  }
                  disabled={loading}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Seleccionar cliente..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">-- Sin cliente --</SelectItem>
                    {clients.map((client) => (
                      <SelectItem key={client._id} value={client._id}>
                        {client.company_name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            {/* Ubicación */}
            {currentPath.length > 0 && (
              <div className="bg-blue-50 p-4 rounded-lg border border-blue-200">
                <p className="text-xs text-blue-600 font-semibold uppercase tracking-wide">
                  📁 Ubicación
                </p>
                <p className="text-sm text-blue-900 mt-1 truncate">
                  {breadcrumbPath}
                </p>
              </div>
            )}

            {/* Zona de Drop */}
            <div>
              <Label className="mb-2 block">Archivo *</Label>
              {!file ? (
                <div
                  onDragEnter={handleDrag}
                  onDragLeave={handleDrag}
                  onDragOver={handleDrag}
                  onDrop={handleDrop}
                  className={`relative flex flex-col items-center justify-center w-full h-40 border-2 border-dashed rounded-lg cursor-pointer transition-all ${
                    dragActive
                      ? 'border-green-500 bg-green-50'
                      : 'border-gray-300 hover:border-green-500 bg-gray-50 hover:bg-green-50'
                  }`}
                >
                  <div className="flex flex-col items-center justify-center pt-5 pb-6">
                    <Cloud className={`w-10 h-10 mb-2 ${
                      dragActive ? 'text-green-500' : 'text-gray-400'
                    }`} />
                    <p className={`text-sm font-semibold ${
                      dragActive ? 'text-green-600' : 'text-gray-600'
                    }`}>
                      {dragActive
                        ? '¡Suelta el archivo aquí!'
                        : 'Arrastra tu archivo aquí'}
                    </p>
                    <p className="text-xs text-gray-500 mt-1">
                      o haz click para seleccionar
                    </p>
                  </div>
                  <input
                    id="file-input"
                    type="file"
                    className="hidden"
                    onChange={handleFileChange}
                    accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png"
                  />
                  <label
                    htmlFor="file-input"
                    className="absolute inset-0 cursor-pointer"
                  />
                </div>
              ) : (
                <div className="flex items-center justify-between p-4 bg-green-50 border-2 border-green-200 rounded-lg">
                  <div className="flex items-center space-x-3">
                    <File className="w-8 h-8 text-green-600 flex-shrink-0" />
                    <div>
                      <p className="text-sm font-medium text-gray-900">
                        {file.name}
                      </p>
                      <p className="text-xs text-gray-500">
                        {(file.size / 1024 / 1024).toFixed(2)} MB
                      </p>
                    </div>
                  </div>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={handleRemoveFile}
                    className="hover:bg-red-100 text-red-600"
                  >
                    <X className="w-4 h-4" />
                  </Button>
                </div>
              )}
              <p className="text-xs text-gray-500 mt-2">
                Formatos permitidos: PDF, DOC, DOCX, XLS, XLSX, JPG, PNG (máx 10MB)
              </p>
            </div>

            {/* Progreso */}
            {loading && uploadProgress > 0 && (
              <div>
                <div className="flex justify-between text-xs mb-1">
                  <span className="text-gray-600">Subiendo...</span>
                  <span className="text-gray-600 font-semibold">{uploadProgress}%</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div
                    className="bg-gradient-to-r from-green-500 to-green-600 h-2 rounded-full transition-all duration-300"
                    style={{ width: `${uploadProgress}%` }}
                  />
                </div>
              </div>
            )}

            {/* Título */}
            <div>
              <Label htmlFor="title" className="font-semibold">
                Título del Documento *
              </Label>
              <Input
                id="title"
                value={formData.title}
                onChange={(e) =>
                  setFormData({ ...formData, title: e.target.value })
                }
                placeholder="Ej: Auditoría ISO 9001"
                disabled={loading}
              />
            </div>

            {/* Descripción */}
            <div>
              <Label htmlFor="description" className="font-semibold">
                Descripción
              </Label>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) =>
                  setFormData({ ...formData, description: e.target.value })
                }
                placeholder="Detalles adicionales del documento..."
                rows={2}
                disabled={loading}
              />
            </div>

            {/* Tipo de Documento */}
            <div>
              <Label htmlFor="document_type" className="font-semibold">
                Tipo de Documento *
              </Label>
              <Select
                value={formData.document_type}
                onValueChange={(value) =>
                  setFormData({ ...formData, document_type: value })
                }
                disabled={loading}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="report">📊 Reporte</SelectItem>
                  <SelectItem value="certification">✓ Certificación</SelectItem>
                  <SelectItem value="manual">📖 Manual</SelectItem>
                  <SelectItem value="permit">📜 Permiso</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Proyecto */}
            <div>
              <Label htmlFor="project_id" className="font-semibold">
                Proyecto (Opcional)
              </Label>
              {projects.length > 0 ? (
                <Select
                  value={formData.project_id}
                  onValueChange={(value) =>
                    setFormData({ ...formData, project_id: value })
                  }
                  disabled={loading}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Seleccionar proyecto..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">-- Sin proyecto --</SelectItem>
                    {projects.map((project) => (
                      <SelectItem key={project._id} value={project._id}>
                        {project.project_name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              ) : (
                <div className="p-3 bg-gray-50 rounded-lg text-xs text-gray-600 border border-gray-200">
                  No hay proyectos disponibles para este cliente
                </div>
              )}
            </div>
          </div>

          <DialogFooter className="gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              disabled={loading}
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={loading || !file || !formData.title.trim()}
              className="bg-green-600 hover:bg-green-700 disabled:opacity-50"
            >
              {loading ? (
                <>
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2" />
                  Subiendo...
                </>
              ) : (
                <>
                  <Upload className="w-4 h-4 mr-2" />
                  Subir Documento
                </>
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default UploadDocumentModalImproved;
